namespace Glide.Core.Settings;

/// <summary>
/// Canonical user-facing settings catalogue. Search, diagnostics and profiles consume this metadata;
/// feature code must not invent hidden one-off settings. Entries may describe later-phase controls,
/// but those controls must remain visibly disabled until their owning subsystem has a real effect path.
/// </summary>
public static class SettingsCatalog
{
    public static IReadOnlyList<SettingDefinition> All { get; } = StaticEntries().Concat(GestureEntries()).ToArray();

    /// <summary>
    /// One entry per gesture row (id "gesture.&lt;slotId&gt;") plus the custom-gesture block. Generated from
    /// <see cref="Glide.Core.Commands.GestureCatalog"/> so a new row can never be missing from search.
    /// </summary>
    private static IEnumerable<SettingDefinition> GestureEntries()
    {
        foreach (var slot in Glide.Core.Commands.GestureCatalog.Slots)
            yield return GestureEntry(slot);
        yield return new("gesture.custom", "Mouse & keyboard", "Custom gestures",
            "Add up to 6 custom gestures per area: pick an input (click, double click, drag or wheel), an optional key to hold (Ctrl, Shift or Alt) and what it does. A custom gesture overrides the built-in row for the same input and key; the first matching custom gesture wins.",
            SettingKind.Action, "Configure",
            ["custom", "custom gesture", "gesture", "mouse", "hold", "modifier", "ctrl", "shift", "alt", "click", "wheel", "drag", "add"]);
    }

    private static SettingDefinition GestureEntry(Glide.Core.Commands.GestureSlotDefinition slot)
    {
        var area = Glide.Core.Commands.GestureCatalog.AreaLabel(slot.Area);
        var wheel = slot.Kind == Glide.Core.Commands.GestureInputKind.Wheel;
        var label = $"{area}: {slot.InputLabel}{(wheel ? " (scroll)" : string.Empty)}";
        Glide.Core.Commands.GestureCatalog.DefaultBehavior.TryGetValue(slot.Id, out var behaviour);
        var description = $"What {slot.InputLabel.ToLowerInvariant()} does in the {area} area. Default ({behaviour ?? "Glide default"}). Only actions that make sense for this input are offered.";
        var terms = new List<string> { "gesture", "mouse", area.ToLowerInvariant(), slot.InputLabel.ToLowerInvariant() };
        terms.AddRange(slot.Area switch
        {
            Glide.Core.Commands.GestureAreas.Windowed => new[] { "windowed", "window", "image", "picture" },
            Glide.Core.Commands.GestureAreas.Fullscreen => new[] { "fullscreen", "full screen", "image" },
            Glide.Core.Commands.GestureAreas.Background => new[] { "background", "empty", "letterbox", "window" },
            Glide.Core.Commands.GestureAreas.Selection => new[] { "selection", "select", "zoom" },
            Glide.Core.Commands.GestureAreas.Slideshow => new[] { "slideshow", "slide show" },
            Glide.Core.Commands.GestureAreas.Overlay => new[] { "overlay", "window in window" },
            Glide.Core.Commands.GestureAreas.Tabs => new[] { "tab", "tabs", "tab strip" },
            Glide.Core.Commands.GestureAreas.TitleBar => new[] { "title bar", "titlebar", "caption", "window" },
            _ => new[] { "explorer", "browser", "folder", "files" }
        });
        terms.AddRange(slot.Input switch
        {
            Glide.Core.Commands.GestureInputs.LeftClick => new[] { "click", "left click" },
            Glide.Core.Commands.GestureInputs.RightClick => new[] { "click", "right click" },
            Glide.Core.Commands.GestureInputs.MiddleClick => new[] { "click", "middle click", "wheel click" },
            Glide.Core.Commands.GestureInputs.DoubleLeft => new[] { "double click", "double-click" },
            Glide.Core.Commands.GestureInputs.DoubleRight => new[] { "double click", "double right" },
            Glide.Core.Commands.GestureInputs.LeftDrag => new[] { "drag", "left drag" },
            Glide.Core.Commands.GestureInputs.RightDrag => new[] { "drag", "right drag" },
            Glide.Core.Commands.GestureInputs.MiddleDrag => new[] { "drag", "middle drag" },
            Glide.Core.Commands.GestureInputs.RightWheel => new[] { "wheel", "scroll", "right button", "hold right" },
            Glide.Core.Commands.GestureInputs.BackButton => new[] { "click", "side button", "back button", "mouse back", "xbutton1", "mouse 4", "mouse4", "thumb button", "browser back" },
            Glide.Core.Commands.GestureInputs.ForwardButton => new[] { "click", "side button", "forward button", "mouse forward", "xbutton2", "mouse 5", "mouse5", "thumb button", "browser forward" },
            _ => new[] { "wheel", "scroll", "mouse wheel" }
        });
        if (slot.Modifier != Glide.Core.Commands.GestureModifiers.None) terms.Add(Glide.Core.Commands.GestureModifiers.Label(slot.Modifier).ToLowerInvariant());
        if (!string.IsNullOrWhiteSpace(behaviour)) terms.Add(behaviour);
        return new SettingDefinition("gesture." + slot.Id, "Mouse & keyboard", label, description, SettingKind.Action, "Configure",
            terms.Distinct(StringComparer.OrdinalIgnoreCase).ToArray());
    }

