        new("status.alignment", "Tabs & status bar", "Status bar position", "Place the floating status bar at the Center (default), Left or Right of the window. You can also right-click the status bar to change this. When collapsed, the button stays where the collapse button was.", SettingKind.Choice, "Center", ["status", "position", "alignment", "align", "left", "right", "center", "centre", "move"]),
        new("status.collapsedCorner", "Tabs & status bar", "Collapsed status button in corner", "When the status bar is collapsed, always park the expand button in the lower-right corner so it stays away from the image. Turn off to keep it where the collapse button was.", SettingKind.Toggle, true, ["status", "collapse", "collapsed", "minimize", "expand", "button", "corner", "lower right", "bottom right"]),
        new("status.autoHide", "Tabs & status bar", "Auto-hide status bar", "Works like Windows' taskbar auto-hide: the status bar is fully hidden (no arrow, no button) and appears only when the pointer enters the invisible reveal zone at the bottom of the window (see Status bar reveal area adjustment). It hides again shortly after the pointer leaves the bar, and it never hides while the pointer is over the bar or one of its menus. Off by default. You can also right-click the status bar and choose Auto-hide status bar.", SettingKind.Toggle, false, ["status", "status bar", "auto hide", "autohide", "auto-hide", "hide", "hidden", "taskbar", "bottom edge", "reveal", "appear", "hover", "disappear", "context menu"]),
        new("status.reserveFitSpace", "Tabs & status bar", "Reserve status bar space when fitting", "Off (default): the image uses the whole window and the status bar floats over it. On: Fit, Fit to window, Fit width, Fit height and the default view size the image to the area above the visible status bar, and re-fit when the bar collapses, expands, hides or changes size. You can also toggle this from the status bar's right-click menu.", SettingKind.Toggle, false, ["status", "status bar", "fit", "reserve", "space", "inset", "overlap", "cover", "covers", "image area", "sizing", "above status bar"]),
        new("status.stackInfoLine", "Tabs & status bar", "Always stack the information on a separate line", "On (default): the file information (name, position, size, zoom) always sits on its own line at the top of the status bar, with the minimise and close buttons at its right and the button groups on the row below, even when everything would fit on one line in a wide window. Off: wide windows keep the information, the buttons and the minimise / close buttons on a single line, and the bar only wraps when the window is narrow. When the buttons themselves do not fit they still wrap onto more rows. You can also toggle this from the status bar's right-click menu.", SettingKind.Toggle, true, ["status", "status bar", "stack", "stacked", "separate line", "own line", "info line", "information line", "file info", "two rows", "2 rows", "rows", "wrap", "wrapping", "layout", "compact", "single line", "one line", "taller", "height"]),
        new("status.gifOnlyOnGifs", "Tabs & status bar", "Show GIF controls only on GIFs", "Off (default): the GIF play / pause and frame buttons always sit in the status bar and are greyed out when the current image is not an animated GIF, so the bar does not change size while you browse. On: the GIF buttons appear only while an animated GIF is open (the behaviour before 5.0.3). Also in the status bar's right-click menu.", SettingKind.Toggle, false, ["gif", "animated", "animation", "frame", "play", "pause", "status", "status bar", "greyed", "grayed", "disabled", "only on gifs", "hide gif controls", "context menu"]),
        new("status.fileNameClickActions", "Tabs & status bar", "Click the file name to rename / open its location", "Off (default). On: a single click on the file name in the status bar starts Rename, and a double-click opens the file's folder in Windows Explorer with the file selected.", SettingKind.Toggle, false, ["status", "status bar", "file name", "filename", "name", "click", "single click", "double click", "rename", "open file location", "show in folder", "explorer"]),
        new("status.customizeButtons", "Tabs & status bar", "Customize status-bar buttons", "Choose which status-bar button groups are shown (zoom, fit, info, settings, save, overlays, GIF, slideshow, navigation) and put them in your own order, like the title-bar buttons.", SettingKind.Action, "Configure", ["status", "status bar", "buttons", "icons", "reorder", "order", "customize", "customise", "hide button", "show button", "toolbar"]),
        new("status.revealZoneExpand", "Tabs & status bar", "Status bar reveal area adjustment", "Fine-tunes the invisible hover area that reveals a collapsed or auto-hidden status bar, in DIP (-40 to +300, default 0). 0 means exactly the size of the status bar: its real box, a thin strip in a wide window or a taller box when the bar wraps into several rows, following its Left / Center / Right position. Positive values grow the area outward on every side (clamped to the window); negative values shrink it inward (never below 6 DIP tall and 40 DIP wide). The area is not drawn, does not block clicks or gestures on the image, and does nothing while you are dragging. A revealed bar stays while the pointer is over it and hides shortly after the pointer leaves it.", SettingKind.Number, 0, ["status", "status bar", "reveal", "reveal area", "reveal zone", "hover", "hover area", "hover zone", "trigger", "trigger area", "trigger zone", "zone", "area", "adjust", "adjustment", "expand", "grow", "shrink", "margin", "padding", "hot zone", "hot edge", "bottom edge", "bottom", "size", "auto-hide", "autohide", "collapsed", "appear", "show", "sensitivity", "bigger", "larger", "smaller"]),

